mapper.select:
SELECT id, type, post_id AS postId, reply_id AS replyId, title, content, CASE WHEN is_read = 1 THEN 1 ELSE 0 END AS isRead, DATE_FORMAT(create_time, '%Y-%m-%d %H:%i') AS createdAt FROM community_notification WHERE user_id = #{userId} AND is_delete = 0
AND is_read = #{isRead}
AND type = #{type}
ORDER BY create_time DESC
